/// Added Filename for Print management settings
/// </summary>
[ExtensionOf(classStr(SRSPrintDestinationSettingsDelegates))]
final class METSRSPrintDestinationSettingsDelegates_Extension
{
}

Method.Source:
/// <summary>
/// Added to consider File name
/// </summary>
/// <param name = "settingsForm">settingsForm</param>
/// <param name = "settings">settings</param>
public void onFormCloseOk(FormRun settingsForm, SRSPrintDestinationSettings settings)
{
    next onFormCloseOk(settingsForm, settings);

    FormStringControl metFileName = settingsForm.design().controlName(formControlStr(SRSPrintDestinationSettingsForm, MetFileName));
    if(metFileName)
    {
        settings.parmFileName(metFileName.valueStr());
        settings.fileName(metFileName.valueStr());
    }
}

/// <summary>
/// Publisher for initial completed event on the destination form.
/// </summary>
/// <param name = "settingsForm">The print destination form.</param>
public void onInitCompleted(FormRun settingsForm)
{
    next onInitCompleted(settingsForm);

    SRSPrintDestinationSettings printSettings;
    container                   printSettingsPack;
    FormStringControl           metFileName = settingsForm.control(settingsForm.controlId(formControlStr(SRSPrintDestinationSettingsForm, MetFileName)));

    printSettingsPack = settingsForm.printDestinationSettings().pack();
    printSettings = new SRSPrintDestinationSettings(printSettingsPack);

    metFileName.text(printSettings.fileName());
}
